        limits: { roomSeats: ROOM_LIMITS.maxSeats, sendHz: Math.min(m.features.rooms?.sendHz ?? 20, ROOM_LIMITS.sendHzMax), maxFrameBytes: ROOM_LIMITS.maxDataFrame, npcDecisionsPerMin: NPC_LIMITS.perUserPerMin }
