class Buckets {
  now;
  b = new Map;
  constructor(now) {
    this.now = now;
  }
  take(key2, perSec, burst) {
    const t2 = this.now();
    const cur = this.b.get(key2) ?? { tokens: burst, at: t2 };
    const tokens2 = Math.min(burst, cur.tokens + (t2 - cur.at) / 1000 * perSec);
    if (tokens2 < 1) {
      this.b.set(key2, { tokens: tokens2, at: t2 });
      return Math.ceil((1 - tokens2) / perSec * 1000);
    }
    this.b.set(key2, { tokens: tokens2 - 1, at: t2 });
    if (this.b.size > 5000) {
      for (const [k, v] of this.b)
        if (t2 - v.at > 60000)
          this.b.delete(k);
    }
    return 0;
  }
  clear() {
    this.b.clear();
  }
}

