  if (!openssl)
    return { ok: false, reason: "openssl was not found on PATH" };
  const tag = randomHex(6);
  const cfgPath = join9(dataDir, `.lan-cert-${tag}.cnf`);
  const tmpCert = join9(dataDir, `.lan-cert-${tag}.pem`);
  const tmpKey = join9(dataDir, `.lan-key-${tag}.pem`);
  const alt = [...names.dns.map((d, i2) => `DNS.${i2 + 1} = ${d}`), ...names.ips.map((ip, i2) => `IP.${i2 + 1} = ${ip}`)].join(`
`);
