    u.searchParams.set("cli", o.version);
    const res = await (o.fetch ?? fetch)(u, { headers: { accept: "application/json", [HEADERS.client]: `cli/${o.version}` }, redirect: "error", signal: AbortSignal.timeout(2500) });
