function usage() {
  const rows = Object.entries(COMMANDS).map(([n, c]) => `  ${n.padEnd(12)}${c.summary}`);
  return `osg ${CLI_VERSION2}: build, test and publish games on oursilly.games

usage: osg <command> [options]

commands:
${rows.join(`
`)}

Run \`osg <command> --help\` for options. \`osg --version\` prints the version.
`;
}
async function main(argv, ctx = defaultCtx()) {
  const [first, ...rest] = argv;
  if (first === undefined || first === "--help" || first === "-h" || first === "help") {
    ctx.out.log(usage());
    return first === undefined ? 2 : 0;
  }
  if (first === "--version" || first === "-V" || first === "version") {
    ctx.out.log(ctx.version);
    return 0;
  }
  const cmd = COMMANDS[first];
  if (!cmd) {
    ctx.out.err(`osg: unknown command "${sanitize(first, 40)}"

${usage()}`);
    return 2;
  }
  try {
    if (rest.includes("--help") || rest.includes("-h")) {
      ctx.out.log(helpFor(first, cmd.usage, cmd.flags));
      return 0;
    }
    const parsed = parseArgs(rest, cmd.flags);
    return await cmd.run(parsed, ctx);
  } catch (e) {
    if (e instanceof UsageError) {
      ctx.out.err(`osg ${first}: ${e.message}`);
      return 2;
    }
    if (e instanceof CliError) {
      ctx.out.err(`osg ${first}: ${e.message}`);
      if (e.hint)
        ctx.out.err(`  ${e.hint}`);
      return e.exitCode;
    }
    const msg2 = e instanceof Error ? e.message : String(e);
    ctx.out.err(`osg ${first}: unexpected error: ${sanitize(msg2, 300)}`);
    if (ctx.env.OSG_DEBUG && e instanceof Error && e.stack)
      ctx.out.err(e.stack);
    return 1;
  }
}

// src/bin.ts
try {
  process.exit(await main(process.argv.slice(2)));
} catch (e) {
  if (!(e instanceof CliError))
    throw e;
  process.stderr.write(`osg: ${e.message}
${e.hint ? `  ${e.hint}
` : ""}`);
  process.exit(e.exitCode);
}
